"""Opt-in quality-stopped relaxation with the original complete-patch fallback.

Only clone dependencies of the existing descent kernel. Boundary construction,
profile projection, final-coordinate guards and original group users remain
unchanged. This factory does not install or adopt the experimental candidate.
"""
import hashlib

import bpy

from . import curved_quad_relax_nodes as relax
from .curved_quad_fair_nodes import assign_group

c = relax.c


def supports(tree):
    name = tree.name
    return ((name.startswith('Prochitecture Streets / Original curved profiled patch')
             and 'Local frame v4' in name) or
            (name.startswith('Prochitecture Streets / Original compound profiled patch')
             and 'Original Section spans' in name and name.endswith('Local frame v1')))


def build(original, *, quality_ramp=False, max_step=2., settled_tolerance=0.):
    if not supports(original):
        raise ValueError('Quality stopping requires a framed original-port or compound patch')
    variant = 'ramp v1' if quality_ramp else 'v1'
    if settled_tolerance: variant = 'settled '+repr(float(settled_tolerance))+' v1'
    if max_step != 2.: variant += ' step '+repr(float(max_step))
    name = ('Prochitecture Streets / Checked quality stop '+variant+' / ')+hashlib.sha256(
        original.name.encode()).hexdigest()[:16]
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    memo = {}; changed = []

    def clone(tree):
        if tree.as_pointer() in memo:
            return memo[tree.as_pointer()]
        if tree.name.startswith('Prochitecture Streets / Pinned curved quad descent v1'):
            if 'Compact iteration state' in tree.name or 'Quality stop' in tree.name:
                raise ValueError('Unsupported or already modified descent: '+tree.name)
            result = relax.build(
                lazy_scalar='Independent scalar' in tree.name,
                stable_difference='Stable energy change' in tree.name,
                captured_gradient='Captured gradient state' in tree.name,
                skip_stalled='Exact minimum-step fixed point' in tree.name,
                inline_trials='Inline trial fields' in tree.name,
                vector_fields='Native planar vectors' in tree.name,
                quality_stop=True, quality_ramp=quality_ramp,max_step=max_step,settled_tolerance=settled_tolerance)
            changed.append(tree.name)
        else:
            children = [(node.name, clone(node.node_tree)) for node in tree.nodes
                        if node.type == 'GROUP' and node.node_tree]
            replacements = [(key, child) for key, child in children
                            if child != tree.nodes[key].node_tree]
            result = tree.copy() if replacements else tree
            if replacements:
                result.name = 'Prochitecture Streets / Quality stop dependency / '+hashlib.sha256(
                    tree.name.encode()).hexdigest()[:16]
                for key, child in replacements:
                    assign_group(result.nodes[key], child)
        memo[tree.as_pointer()] = result
        return result

    candidate = clone(original)
    if not changed:
        raise ValueError('No shared quad descent dependency found')
    g = c.Graph(name)
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    for socket in sockets:
        g.socket(socket.name, socket.socket_type, socket.in_out,
                 default=getattr(socket, 'default_value', None))
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    fast = g.node('GeometryNodeGroup', 'Quality stop with all original patch guards')
    fast.node_tree = candidate
    fallback = g.node('GeometryNodeGroup', 'Original patch after quality-stop rejection')
    fallback.node_tree = original
    for socket in sockets:
        if socket.in_out == 'INPUT':
            for call in (fast, fallback):
                g.bind(inp.outputs[socket.name], call.inputs[socket.name])
    use = fast.outputs['Valid']
    for socket in sockets:
        if socket.in_out != 'OUTPUT':
            continue
        kind = {'NodeSocketBool': 'BOOLEAN', 'NodeSocketGeometry': 'GEOMETRY'}[socket.socket_type]
        chosen = c.choose(g, use, fast.outputs[socket.name], fallback.outputs[socket.name], kind)
        if socket.name in ('Geometry', 'Inspection Geometry', 'Status'):
            chosen = c._store(g, chosen, 'st_cq_quality_candidate', use, 'BOOLEAN')
        g.bind(chosen, out.inputs[socket.name])
    g.g['st_quality_stop_original'] = original.name
    g.g['st_quality_stop_ramp'] = quality_ramp
    g.g['st_quality_stop_max_step'] = max_step
    g.g['st_quality_stop_settled_tolerance'] = settled_tolerance
    g.g['st_quality_stop_dependencies'] = sorted(set(changed))
    return g.g
